ucs.falcon_logscale_query:
#event_simpleName=FileWritten (TargetFileName=/\\(zam64|zam|powertool64|powertool|gmer64|gmer|kpcr|truesight|rentdrv2|aswarpot|viragt64)\.sys$/i OR TargetFileName=/\\akira_readme\.txt$/i OR TargetFileName=/\\fn\.txt$/i OR TargetFileName=/\.(akira|powerranges)$/i)
| ContextImageFileName!=/\\(MsMpEng|TrustedInstaller|msiexec)\.exe$/i
| case {
    TargetFileName=/\.(akira|powerranges)$/i OR TargetFileName=/\\(akira_readme|fn)\.txt$/i
      | RansomMarker:="true";
    *
      | DriverDrop:="true";
  }
| groupBy([aid, ComputerName], function=[count(field=DriverDrop, as=drivers), count(field=RansomMarker, as=markers), min(@timestamp, as=firstObserved), max(@timestamp, as=lastObserved), collect([TargetFileName, ContextImageFileName])])
| drivers >= 1
| markers >= 1
